(function(){if(window.__billdrTabs)return;window.__billdrTabs=1;var DUR=6000;function init(){var wrap=document.querySelector('.features_tabs');if(!wrap)return;var links=[].slice.call(wrap.querySelectorAll('.w-tab-link'));if(links.length<2)return;var rm=matchMedia('(prefers-reduced-motion:reduce)').matches;var timer=null,visible=false;function rule(l){return l?l.querySelector('.features_tab-rule'):null}function cur(){return wrap.querySelector('.w-tab-link.w--current')||links[0]}function clearAll(){links.forEach(function(l){var r=rule(l);if(r){r.style.transition='none';r.style.width='0%';}})}function fill(ms){var r=rule(cur());if(!r)return;void r.offsetWidth;r.style.transition='width '+ms+'ms linear';r.style.width='100%';}function run(){clearTimeout(timer);clearAll();fill(DUR);if(rm||!visible)return;timer=setTimeout(next,DUR);}function next(){var i=links.indexOf(cur());links[(i+1)%links.length].click();}links.forEach(function(l){l.addEventListener('click',function(){setTimeout(run,20)})});if('IntersectionObserver' in window){new IntersectionObserver(function(e){var v=e[0].isIntersecting;if(v===visible)return;visible=v;if(v){run();}else{clearTimeout(timer);}},{threshold:0.25}).observe(wrap);}else{visible=true;run();}}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();